<!doctype html><html lang="id"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>PPPoE Dashboard - NetMonitor</title><link rel="stylesheet" href="../assets/css/variables.css?v=8"><link rel="stylesheet" href="../assets/css/common.css?v=8"><link rel="stylesheet" href="../assets/css/theme.css?v=1"><link rel="stylesheet" href="https://cdn.jsdelivr.net/npm/bootstrap-icons@1.11.3/font/bootstrap-icons.min.css"><link rel="stylesheet" href="../assets/css/pppoe_subpage.css?v=1"><link rel="stylesheet" href="../assets/css/pppoe_dashboard_pro.css?v=1"><link rel="stylesheet" href="../assets/css/pppoe_router.css?v=1"></head><body><?php require_once '../includes/sidebar.php'; ?><main class="main-content ppp-subpage"><header class="ppp-head"><div><h1 class="ppp-title">PPPoE Dashboard</h1><div class="ppp-sub">Ringkasan koneksi PPPoE dan bandwidth realtime</div></div><div class="pppoe-actions ppp-actions"><span id="status" class="ppp-status">● Checking...</span><button id="refresh" class="ppp-btn primary">↻ Refresh</button></div></header><section class="ppp-kpis"><div class="ppp-kpi"><span>Active Sessions</span><b id="active">0</b></div><div class="ppp-kpi"><span>Accounts</span><b id="accounts">0</b></div><div class="ppp-kpi"><span>Enabled</span><b id="enabled">0</b></div><div class="ppp-kpi"><span>Profiles</span><b id="profiles">0</b></div></section><section class="ppp-card"><div class="ppp-card-head"><div><h2>PPPoE Management</h2><small>Pilih modul untuk membuka halaman khusus</small></div></div><div class="ppp-body"><div class="ppp-grid"><a class="ppp-tile" href="users.php"><i class="bi bi-people"></i><strong>User Accounts</strong><span>Kelola username, password, profile, enable/disable.</span></a><a class="ppp-tile" href="active.php"><i class="bi bi-broadcast-pin"></i><strong>Active Session</strong><span>Lihat koneksi PPPoE yang sedang online.</span></a><a class="ppp-tile" href="profiles.php"><i class="bi bi-diagram-3"></i><strong>Profile</strong><span>Kelola profile dan rate-limit MikroTik.</span></a><a class="ppp-tile" href="traffic.php"><i class="bi bi-speedometer2"></i><strong>Traffic Ranking</strong><span>Ranking bandwidth realtime dan histori.</span></a><a class="ppp-tile" href="history_index.php"><i class="bi bi-clock-history"></i><strong>Traffic History</strong><span>Histori traffic per user PPPoE.</span></a></div></div></section></main><script src="https://cdn.jsdelivr.net/npm/chart.js@4.4.7/dist/chart.umd.min.js"></script><script src="../assets/js/pppoe_router_selector.js?v=2"></script><script src="../assets/js/pppoe_stats_bus.js?v=2"></script><script src="../assets/js/pppoe_dashboard_pro.js?v=5"></script><script>const api='../api/pppoe.php',$=id=>document.getElementById(id);async function load(){try{const r=await Promise.all(['active','secrets','profiles'].map(a=>fetch(api+'?action='+a+'&t='+Date.now(),{cache:'no-store'}).then(x=>x.json())));if(r.some(x=>!x.success))throw Error('Gagal mengambil data PPPoE');const a=r[0].users||[],s=r[1].secrets||[],p=r[2].profiles||[];$('active').textContent=a.length;$('accounts').textContent=s.length;$('enabled').textContent=s.filter(x=>!x.disabled).length;$('profiles').textContent=p.length;$('status').textContent='● ONLINE';$('status').className='ppp-status ppp-online'}catch(e){$('status').textContent='● OFFLINE';$('status').className='ppp-status ppp-offline'}}$('refresh').onclick=()=>{load();window.pppoeStatsRefresh?.()};load();setInterval(()=>document.visibilityState==='visible'&&load(),10000);</script></body></html>